{
  "findings": [
    {
      "check_id": "CKV2_AWS_61",
      "title": "S3 lifecycle configuration is missing",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The CloudTrail log bucket has no lifecycle configuration, so incomplete multipart uploads can persist indefinitely and consume storage."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 Public Access Block is missing",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The bucket has no account-independent bucket-level Public Access Block configuration, allowing future ACL or policy changes to expose CloudTrail logs publicly."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 access logging is disabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "Server access logging is not configured, reducing visibility into requests made against the CloudTrail log bucket."
    },
    {
      "check_id": "CKV_AWS_144",
      "title": "S3 cross-region replication is disabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The CloudTrail log bucket has no replication configuration, leaving its contents vulnerable to a regional disruption."
    },
    {
      "check_id": "CKV_AWS_53",
      "title": "Public ACLs are not blocked",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "CRITICAL",
      "explanation": "The bucket does not explicitly block public ACLs, so an accidental ACL change could expose sensitive CloudTrail logs."
    }
  ],
  "patched_code": "variable "cloudtrail_access_log_target_bucket" {
  description = "Name of an existing S3 bucket that receives server access logs for the CloudTrail log bucket."
  type        = string
}

variable "cloudtrail_replication_destination_bucket_arn" {
  description = "ARN of an existing S3 bucket in another AWS region that receives replicated CloudTrail logs."
  type        = string

  validation {
    condition     = can(regex("^arn:[^:]+:s3:::[^/]+$", var.cloudtrail_replication_destination_bucket_arn))
    error_message = "The replication destination must be a valid S3 bucket ARN."
  }
}

variable "cloudtrail_replication_role_arn" {
  description = "ARN of an existing IAM role authorized to replicate objects to the destination bucket."
  type        = string

  validation {
    condition     = can(regex("^arn:[^:]+:iam::[0-9]{12}:role/.+$", var.cloudtrail_replication_role_arn))
    error_message = "The replication role must be a valid IAM role ARN."
  }
}

resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = "smart-city-parking-management-system-s3-cloudtrail-${random_string.cloudtrail_suffix.result}"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "cloudtrail_logs" {
  bucket        = aws_s3_bucket.cloudtrail_logs.id
  target_bucket = var.cloudtrail_access_log_target_bucket
  target_prefix = "cloudtrail-bucket-access-logs/"
}

resource "aws_s3_bucket_lifecycle_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_replication_configuration" "cloudtrail_logs" {
  depends_on = [aws_s3_bucket_versioning.cloudtrail_logs]

  bucket = aws_s3_bucket.cloudtrail_logs.id
  role   = var.cloudtrail_replication_role_arn

  rule {
    id     = "cross-region-replication"
    status = "Enabled"

    destination {
      bucket        = var.cloudtrail_replication_destination_bucket_arn
      storage_class = "STANDARD"
    }
  }
}
",
  "fix_summary": "Added a complete S3 Public Access Block, server access logging, lifecycle cleanup, versioning, and cross-region replication. Existing logging and replication destinations are supplied through validated variables to avoid embedding credentials or inventing unmanaged destination infrastructure."
}
